import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:firebase_messaging/firebase_messaging.dart';class NotificationService{final _db=FirebaseFirestore.instance;Future<void> initialize()async{final user=FirebaseAuth.instance.currentUser;if(user==null)return;await FirebaseMessaging.instance.requestPermission();final token=await FirebaseMessaging.instance.getToken();if(token!=null)await _db.collection('users').doc(user.uid).collection('devices').doc(token).set({'token':token,'updatedAt':FieldValue.serverTimestamp()});FirebaseMessaging.instance.onTokenRefresh.listen((t){_db.collection('users').doc(user.uid).collection('devices').doc(t).set({'token':t,'updatedAt':FieldValue.serverTimestamp()});});}}